>             setTimeout(() => global.startJuryVote?.(), 300);
>             return;
>         }
>         // If more than 3, something is very wrong - log error but continue
>         if(alive.length > 3) {
>             console.error('[F3] More than 3 players remaining, flow should not have been triggered');
>             return;
>         }
>         return;
>     }
>     
>     showFinalWeekAnnouncement();
> }
> ```
> 
> ### 3. Add guard to `finalizeFinal4Eviction()` in `js/veto.js`
> 
> The existing guards check `__f4EvictionResolved` and `__f4EvictionInProgress`, but we should also ensure the function can't be called after transition has started:
> 
> ```javascript
> async function finalizeFinal4Eviction(targetId){
>     var g = global.game;
>     if(g.__f4EvictionResolved) return;
>     if(g.__f4EvictionInProgress) return;
>     if(g.__f4ToF3TransitionStarted) return; // ADD THIS GUARD
>     
>     // ... rest of the function
> }
> ```
> 
> ## Files to Modify
> 
> 1. `js/veto.js` - Add guards to `proceedAfterFinal4Eviction()` and `finalizeFinal4Eviction()`
> 2. `js/competitions.js` - Add player count validation to `startFinal3Flow()`
