**In `style.css`** - Add custom cursor styles:
```css
/* Custom Cursor */
.custom-cursor {
  width: 12px;
  height: 12px;
  background: var(--accent);
  border-radius: 50%;
  position: fixed;
  pointer-events: none;
  z-index: 10000;
  transform: translate(-50%, -50%);
  transition: transform 0.1s ease, background 0.2s ease;
  mix-blend-mode: difference;
}

.cursor-follower {
  width: 40px;
  height: 40px;
  border: 2px solid var(--accent);
  border-radius: 50%;
  position: fixed;
  pointer-events: none;
  z-index: 9999;
  transform: translate(-50%, -50%);
  transition: transform 0.3s ease, width 0.3s ease, height 0.3s ease, border-color 0.3s ease;
}

.custom-cursor.hover {
  transform: translate(-50%, -50%) scale(2);
  background: #ec4899;
}

.cursor-follower.hover {
  width: 60px;
  height: 60px;
  border-color: #ec4899;
}

.custom-cursor.click {
  transform: translate(-50%, -50%) scale(0.8);
}

/* Hide default cursor on desktop */
@media (min-width: 769px) {
  * {
    cursor: none !important;
  }
}

/* Disable custom cursor on mobile */
@media (max-width: 768px) {
  .custom-cursor, .cursor-follower {
    display: none;
  }
}
```

**In `script.js`** - Add cursor tracking:
```javascript
// Custom Cursor
const cursor = document.getElementById('cursor');
const cursorFollower = document.getElementById('cursorFollower');

if (cursor && cursorFollower) {
  document.addEventListener('mousemove', (e) => {
    cursor.style.left = e.clientX + 'px';
    cursor.style.top = e.clientY + 'px';

    setTimeout(() => {
      cursorFollower.style.left = e.clientX + 'px';
      cursorFollower.style.top = e.clientY + 'px';
    }, 80);
  });

  // Hover effect on interactive elements
  const hoverElements = document.querySelectorAll('a, button, .btn, .project-card, .skill-item, .game-tab, .contact-card');

  hoverElements.forEach(el => {
    el.addEventListener('mouseenter', () => {
      cursor.classList.add('hover');
      cursorFollower.classList.add('hover');
    });
    el.addEventListener('mouseleave', () => {
      cursor.classList.remove('hover');
      cursorFollower.classList.remove('hover');
    });
  });

  // Click effect
  document.addEventListener('mousedown', () => cursor.classList.add('click'));
  document.addEventListener('mouseup', () => cursor.classList.remove('click'));
}
```

